import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"镜面锡沉积","description":"","frontmatter":{"title":"镜面锡沉积","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tin-on-mirrors.md","filePath":"litho/tin-on-mirrors.md","lastUpdated":1789023840000}'),d={name:"litho/tin-on-mirrors.md"};function A(B,a,c,m,_,D){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="镜面锡沉积" tabindex="-1">镜面锡沉积 <a class="header-anchor" href="#镜面锡沉积" aria-label="Permalink to &quot;镜面锡沉积&quot;">​</a></h1><div class="epigraph"><p>没被电离打掉、又没变成氢化物抽走的锡，会在第一面光学上长成吸收膜；功率掉的方式与起泡分层不同。</p><footer>—— 改写自 ASML / Cymer 对 LPP 锡污染与氢原位清洗的公开叙述</footer></div><p><a href="/litho/hydrogen-blister">上一课</a>把氢的代价写成膜内起泡。缺口是氢真正要清的那一层：镜面上的锡。本课钉锡沉积（锡镀膜、溅射再沉积）。防护膜如何挡颗粒，留给后课 pellicle，不在这里展开透过率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/tin-debris">碎屑课</a>分过三类：离子溅射、中性蒸汽镀膜、微滴撞击。落到多层上的中性锡和低能再沉积形成连续或岛状金属膜，13.5 nm 吸收截面大，几个纳米量级就够让带内反射率可见地掉。<a href="/litho/collector-lifetime">收集镜寿命</a> 已把这件事写成消耗品曲线；本课补的是沉积本身的空间与化学，以及它和起泡如何叠在同一面镜子上。</p><p>若 DGL 或 IF 通道失手，锡还可以走向照明与投影——那是事故态，不是量产稳态。量产叙述假定锡质量流被关在光源舱，收集镜当牺牲面。缺口是：牺牲面上的锡是均匀吸收还是有角分布，氢洗是在清膜还是在打帽层。</p><h3 id="镀锡与溅射损伤不要一张工单" tabindex="-1">镀锡与溅射损伤不要一张工单 <a class="header-anchor" href="#镀锡与溅射损伤不要一张工单" aria-label="Permalink to &quot;镀锡与溅射损伤不要一张工单&quot;">​</a></h3><p>均匀镀锡：氢自由基生成 SnH₄，反射率可部分恢复。溅射把帽层和周期打薄、打糙：氢补不回。微滴坑是局部几何损伤。只报「镜子脏了」，维护会选错：该换的洗、该洗的换。</p><p><span class="marginnote">锡膜是金属吸收体，不是碳膜。碳氢残余裂解成碳，氢走 CH₄ 通道；锡走 SnH₄。两种污染物的光学后果都是掉 R，化学旋钮不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光源舱维持足够氢密度和 EUV 解离，让收集镜表面处于「镀上–抽走」的准动态平衡。流量、镜温、IF 功率闭环：流量小则锡累积，流量大则沿程吸收吃带内功率，并加重上一课的植入。磁场与缓冲气体先减离子通量，氢再清蒸汽镀层；微滴仍靠靶形态从源头减产。</p><p>监测用 IF 带内功率、光瞳填充和（公开讨论中的）收集镜状态代理。剂量环加激光能量可以短时间顶住瓦数，锡膜加厚时角谱和散射已经变，CD 指纹会先于功率计告警。</p><h3 id="空间指纹跟立体角走" tabindex="-1">空间指纹跟立体角走 <a class="header-anchor" href="#空间指纹跟立体角走" aria-label="Permalink to &quot;空间指纹跟立体角走&quot;">​</a></h3><p>正对等离子体的多层先镀、先溅射；掠入射对照几何里，擦角壳层的镀锡沿缝和阴影不同。无论哪种，污染都不是均匀加一个衰减系数：照明 σ 图会歪。OPC 假定的光源是出厂图，收集镜寿命末期要用光源侧补偿或接受窗口收缩。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中性锡到达后物理吸附、成核、连成膜。后续离子把已镀锡再溅射到别的方位，形成二次污染。氢刻蚀速率依赖自由基通量、表面温度和锡的化学态（金属锡对氧化物）。氧化锡更难氢化，放气与漏水会把「可洗」变成「洗不动」。</p><p>与起泡叠加时：氢流量为清锡而加大，植入通道变宽；锡岛又可能成为局部氢捕获或应力集中。维护策略必须同时看表面金属和膜内鼓包，不能只开大氢。</p><p><span class="marginnote">投影镜上的锡是失败模式。公开量产故事把锡关在收集器一侧。写工艺事故时不要把收集镜氢洗配方套到 POB 上。</span></p>',18)),(e(),s(h,null,{default:r(()=>[p(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEB%5B%22%E4%B8%AD%E6%80%A7%E9%94%A1%20%2F%20%E5%86%8D%E6%B2%89%E7%A7%AF%22%5D%20--%3E%20FILM%5B%22%E9%95%9C%E9%9D%A2%E9%94%A1%E8%86%9C%22%5D%0A%20%20FILM%20--%3E%20ABS%5B%22%E5%B8%A6%E5%86%85%E5%90%B8%E6%94%B6%E6%8E%89%20R%22%5D%0A%20%20FILM%20--%3E%20H%5B%22%E6%B0%A2%E8%87%AA%E7%94%B1%E5%9F%BA%22%5D%0A%20%20H%20--%3E%20VOL%5B%22SnH4%20%E6%8A%BD%E8%B5%B0%22%5D%0A%20%20ION%5B%22%E7%A6%BB%E5%AD%90%E6%BA%85%E5%B0%84%22%5D%20--%3E%20ROUGH%5B%22%E5%B8%BD%E5%B1%82%E4%B8%8E%E5%91%A8%E6%9C%9F%E6%8D%9F%E4%BC%A4%22%5D%0A%20%20DROP%5B%22%E5%BE%AE%E6%BB%B4%22%5D%20--%3E%20PIT%5B%22%E5%9D%91%E4%B8%8E%E4%BA%8C%E6%AC%A1%E5%96%B7%E6%BA%85%22%5D%0A%20%20VOL%20--%3E%20IF%5B%22IF%20%E5%8A%9F%E7%8E%87%E9%83%A8%E5%88%86%E6%81%A2%E5%A4%8D%22%5D%0A%20%20ROUGH%20--%3E%20IF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写电荷态，也不给锡膜厚度的出厂阈值。不要编造收集镜更换小时。后课默认：说到氢，先分清清锡、起泡、沿程吸收三件事。</p><p>LPP 公开材料给出氢清锡的原理与收集镜作为牺牲光学；不给出表面覆盖度诊断配方。</p><p><span class="marginnote">「镜子上有锡」在光源舱是预期消耗；在扫描腔是污染事件。词汇不要混用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中性锡在收集镜上长成吸收膜，是 LPP 的预期消耗通道。</li><li>氢刻蚀可逆地清薄膜锡；溅射与微滴坑清不回。</li><li>污染有角分布，照明光瞳会先于平均功率变坏。</li><li>加大氢清锡会加重起泡，窗口是折中。</li><li>出处：ASML / Cymer LPP 锡污染与氢清洗公开材料。</li></ul>',6))])}const f=o(d,[["render",A]]);export{P as __pageData,f as default};
